// Otomatik üretilir: python3 build.py (kaynak: src/app.html). Elle değiştirme.
module.exports = new Function("\nconst STABLES = new Set(['usdt','usdc','dai','fdusd','usde','tusd','pyusd','usdd','usds','busd','gusd','usdp','frax','lusd','susd','eurc','usdy','usd1','usdg','rlusd','xaut','paxg']);\nconst clamp = (x, a, b) => Math.min(b, Math.max(a, x));\nconst num = (v) => (typeof v === 'number' && isFinite(v) ? v : null);\nconst avg = (a) => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : 0);\n\nfunction mkRe(alts) { return new RegExp('(?:^|[^a-zçğıöşü0-9])(?:' + alts + ')', 'g'); }\nconst POS_RE = mkRe('surge|rall(?:y|ies|ied)|soar|jump|gain|bullish|record high|all-time high|approv|adopt|partnership|launch|upgrade|breakout|inflow|accumulat|rebound|recover|yüksel|rekor|onay|artış|toparlan|ortaklık|beat(?:s)? (?:estimates|expectations)|profit|buyback|dividend|growth|temettü|kâr|büyüme');\nconst NEG_RE = mkRe('crash|plunge|drop|fall|slump|tumble|hack|exploit|lawsuit|sues|ban(?:ned|s)?(?![a-z])|bearish|dump|outflow|liquidat|fraud|scam|rug pull|delist|sell-?off|investigat|collapse|çök|düşüş|düştü|yasak|dava|soruşturma|saldırı|kayıp|miss(?:es|ed)?(?![a-z])|loss(?:es)?(?![a-z])|layoffs?|recession|downgrad|tariff|probe|zarar|iflas|ceza|enflasyon');\nfunction headlineScore(t) {\n  const s = String(t).toLowerCase();\n  const p = (s.match(POS_RE) || []).length, n = (s.match(NEG_RE) || []).length;\n  return clamp(p - n, -2, 2);\n}\nconst escRe = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\nfunction coinMatcher(c) {\n  const parts = [];\n  const raw = String(c.name || '');\n  const names = [raw.replace(/\\s*\\(.*\\)\\s*/g, '').trim(), ...((raw.match(/\\(([^)]+)\\)/g) || []).map((x) => x.slice(1, -1).trim())), ...(c.alias || [])];\n  for (const nm of names) {\n    if (nm.length >= 4) parts.push(new RegExp('(?:^|[^A-Za-z0-9])' + escRe(nm) + '(?![A-Za-z0-9])', 'i'));\n    else if (nm.length >= 3) parts.push(new RegExp('(?:^|[^A-Za-z0-9])' + escRe(nm) + '(?![A-Za-z0-9])'));\n  }\n  const sym = String(c.symbol || '').toUpperCase();\n  if (sym.length >= 3) parts.push(new RegExp('(?:^|[^A-Za-z0-9])' + escRe(sym) + '(?![A-Za-z0-9])'));\n  return (title) => parts.some((re) => re.test(title));\n}\nfunction newsContext(news, coins) {\n  const scored = news.map((n) => ({ ...n, score: headlineScore(n.title) }));\n  const byCoin = {};\n  for (const c of coins) {\n    if ((c.rank || 9999) > 300) continue;\n    const m = coinMatcher(c);\n    const hits = scored.filter((n) => m(n.title));\n    if (hits.length) byCoin[c.id] = hits;\n  }\n  return { scored, byCoin, market: scored.length ? avg(scored.map((n) => n.score)) : 0 };\n}\n\nfunction rsi14(s) {\n  if (s.length < 15) return null;\n  let g = 0, l = 0;\n  for (let i = 1; i <= 14; i++) { const d = s[i] - s[i - 1]; if (d >= 0) g += d; else l -= d; }\n  g /= 14; l /= 14;\n  for (let i = 15; i < s.length; i++) { const d = s[i] - s[i - 1]; g = (g * 13 + Math.max(d, 0)) / 14; l = (l * 13 + Math.max(-d, 0)) / 14; }\n  return l === 0 ? 100 : 100 - 100 / (1 + g / l);\n}\nfunction sparkStats(sp) {\n  if (!sp || sp.length < 20 || sp.some((v) => !(v > 0))) return null;\n  const n = sp.length, h = 168 / n, last = sp[n - 1];\n  const mean = avg(sp);\n  const rets = []; for (let i = 1; i < n; i++) rets.push(Math.log(sp[i] / sp[i - 1]));\n  const mu = avg(rets), sd = Math.sqrt(avg(rets.map((r) => (r - mu) ** 2)));\n  const step = Math.max(1, Math.round(4 / h)), s4 = [];\n  for (let i = n - 1; i >= 0; i -= step) s4.unshift(sp[i]);\n  const hi = Math.max(...sp), lo = Math.min(...sp);\n  const i24 = Math.max(0, n - 1 - Math.round(24 / h));\n  return { last, trend: (last / mean - 1) * 100, vol: sd * Math.sqrt(24 / h) * 100, rsi: rsi14(s4), hi, lo, c7: (last / sp[0] - 1) * 100, c24: (last / sp[i24] - 1) * 100 };\n}\n\nconst fmtP = (v, d = 1) => (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(d).replace('.', ',') + '%';\nconst f1 = (v) => Math.abs(v).toFixed(1).replace('.', ',');\n\nfunction analyze(c, ctx) {\n  const st = sparkStats(c.spark);\n  const isStable = STABLES.has(String(c.symbol).toLowerCase());\n  if (isStable) return { signal: 'STABİL', cls: 's-stable', score: 0, risk: 'Düşük', reasons: [{ pos: null, t: 'Değeri bir varlığa sabitlenmiş (stabil/pegli) bir token. Al-sat sinyali üretilmez.' }], st };\n  const c24 = num(c.c24) ?? st?.c24 ?? 0;\n  const c7 = num(c.c7) ?? st?.c7 ?? 0;\n  const c30 = num(c.c30);\n  const R = [];\n  let score = 0;\n\n  const m7 = clamp(c7, -30, 30) / 30 * 30; score += m7;\n  if (c7 >= 15) R.push({ pos: true, t: `Son 7 günde ${fmtP(c7)}: güçlü yukarı momentum.` });\n  else if (c7 >= 3) R.push({ pos: true, t: `Son 7 günde ${fmtP(c7)}: ılımlı yükseliş.` });\n  else if (c7 <= -15) R.push({ pos: false, t: `Son 7 günde ${fmtP(c7)}: belirgin satış baskısı.` });\n  else if (c7 <= -3) R.push({ pos: false, t: `Son 7 günde ${fmtP(c7)}: zayıf seyir.` });\n  else R.push({ pos: null, t: `Son 7 günde ${fmtP(c7)}: yatay seyir.` });\n\n  if (c30 !== null) {\n    score += clamp(c30, -50, 50) / 50 * 20;\n    if (c30 >= 20) R.push({ pos: true, t: `30 günlük trend yukarı (${fmtP(c30, 0)}).` });\n    else if (c30 <= -20) R.push({ pos: false, t: `30 günlük trend aşağı (${fmtP(c30, 0)}).` });\n  }\n  score += clamp(c24, -10, 10);\n  if (c24 > 25) { score -= 15; R.push({ pos: false, t: `24 saatte ${fmtP(c24, 0)} sıçradı. Ani yükselişlerin ardından geri çekilme sık görülür, kovalamak riskli.` }); }\n  else if (c24 < -10) R.push({ pos: false, t: `Son 24 saatte ${fmtP(c24)} düştü.` });\n  if (c7 > 60) { score -= 15; R.push({ pos: false, t: 'Haftalık artış çok sert; aşırı ısınma ihtimali yüksek.' }); }\n\n  let vol = null;\n  if (st) {\n    score += clamp(st.trend, -8, 8) / 8 * 10;\n    if (st.trend > 3) R.push({ pos: true, t: `Fiyat 7 günlük ortalamasının %${f1(st.trend)} üstünde.` });\n    else if (st.trend < -3) R.push({ pos: false, t: `Fiyat 7 günlük ortalamasının %${f1(st.trend)} altında.` });\n    vol = st.vol;\n    if (st.rsi !== null) {\n      const r = st.rsi;\n      if (r >= 75) { score -= 15; R.push({ pos: false, t: `RSI ${r.toFixed(0)}: aşırı alım bölgesi, geri çekilme riski yüksek.` }); }\n      else if (r >= 65) { score -= 5; R.push({ pos: false, t: `RSI ${r.toFixed(0)}: alım bölgesi sınırında, ivme zayıflayabilir.` }); }\n      else if (r >= 45) { score += 5; }\n      else if (r <= 30) { score += 8; R.push({ pos: true, t: `RSI ${r.toFixed(0)}: aşırı satım bölgesi, tepki yükselişi ihtimali var (düşüş sürebilir).` }); }\n    }\n  }\n  const liq = c.mcap > 0 && c.vol > 0 ? c.vol / c.mcap : null;\n  if (liq !== null) {\n    if (liq < 0.02) { score -= 5; R.push({ pos: false, t: `Günlük hacim piyasa değerinin yalnızca %${f1(liq * 100)}'i: alım satımda fiyat kayması riski.` }); }\n    else if (liq > 0.08) { score += 3; R.push({ pos: true, t: `İşlem hacmi güçlü (piyasa değerinin %${f1(liq * 100)}'i).` }); }\n  }\n  const rank = c.rank || 9999;\n  if (rank > 200) score -= 5; else if (rank > 100) score -= 2;\n  if (num(c.ath) !== null && c.ath < -80) R.push({ pos: null, t: `Zirvesinin %${f1(c.ath)} altında; toparlanma uzun sürebilir.` });\n\n  const hits = ctx.byCoin[c.id] || [];\n  if (hits.length) {\n    const a = avg(hits.map((h) => h.score));\n    score += clamp(a * 5, -10, 10);\n    if (a > 0.3) R.push({ pos: true, t: `Haberlerde olumlu söz edilmiş (${hits.length} başlık).` });\n    else if (a < -0.3) R.push({ pos: false, t: `Haberlerde olumsuz söz edilmiş (${hits.length} başlık).` });\n    else R.push({ pos: null, t: `Haberlerde geçiyor (${hits.length} başlık), tonu nötr.` });\n  }\n  score += clamp(ctx.market * 5, -5, 5);\n  if (ctx.market > 0.3) R.push({ pos: true, t: 'Genel haber akışı olumlu.' });\n  else if (ctx.market < -0.3) R.push({ pos: false, t: 'Genel haber akışı olumsuz.' });\n\n  score = Math.round(clamp(score, -100, 100));\n  const hot = c24 > 25 || c7 > 60 || (st && st.rsi !== null && st.rsi >= 75);\n  let signal, cls;\n  if (score >= 45) { signal = 'GÜÇLÜ AL'; cls = 's-strongbuy'; }\n  else if (score >= 20) { signal = 'AL'; cls = 's-buy'; }\n  else if (score > -10) { signal = 'BEKLE'; cls = 's-hold'; }\n  else if (score > -30) { signal = 'AZALT'; cls = 's-reduce'; }\n  else { signal = 'SAT'; cls = 's-sell'; }\n  if (hot && score >= 20) {\n    signal = 'BEKLE'; cls = 's-hold';\n    R.unshift({ pos: false, t: 'Aşırı ısınma nedeniyle sinyal \"bekle\" seviyesine çekildi. Yükselişi kovalamak yerine geri çekilmeyi beklemek daha güvenli.' });\n  }\n\n  let risk = 'Düşük';\n  if ((vol !== null && vol > 8) || rank > 300) risk = 'Yüksek';\n  else if ((vol !== null && vol > 4) || rank > 100) risk = 'Orta';\n  if (vol !== null) R.push({ pos: null, t: `Günlük oynaklık yaklaşık %${f1(vol)}; risk seviyesi ${risk.toLowerCase()}.` });\n  return { signal, cls, score, risk, reasons: R, st, hot, hits, liq, vol };\n}\n\nconst moodLabel = (m) => (m < -25 ? 'Korku' : m < -8 ? 'Temkinli' : m < 15 ? 'Nötr' : m < 35 ? 'İştahlı' : 'Aşırı iştah');\nfunction analyzeAll(coins, news) {\n  const ctx = newsContext(news, coins);\n  for (const c of coins) c.a = analyze(c, ctx);\n  const body = coins.filter((c) => c.a.signal !== 'STABİL' && (c.rank || 9999) <= 100);\n  const m = body.length ? avg(body.map((c) => c.a.score)) : 0;\n  const mood = moodLabel(m);\n  const tally = { buy: 0, hold: 0, sell: 0 };\n  for (const c of coins) { if (c.a.signal === 'GÜÇLÜ AL' || c.a.signal === 'AL') tally.buy++; else if (c.a.signal === 'BEKLE') tally.hold++; else if (c.a.signal !== 'STABİL') tally.sell++; }\n  return { ctx, mood, moodScore: m, tally };\n}\n\n// Örnek veri: sunucu bağlı değilken arayüzü göstermek için. Gerçek piyasa değerleri değildir.\nfunction rng(seed) { return () => { seed |= 0; seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }\nconst DEMO_LIST = [['bitcoin','btc','Bitcoin',64000,1250],['ethereum','eth','Ethereum',3100,370],['tether','usdt','Tether',1,110],['ripple','xrp','XRP',0.62,34],['binancecoin','bnb','BNB',580,85],['solana','sol','Solana',150,70],['usd-coin','usdc','USDC',1,34],['dogecoin','doge','Dogecoin',0.14,20],['tron','trx','TRON',0.13,11],['cardano','ada','Cardano',0.45,16],['chainlink','link','Chainlink',14,8.5],['avalanche-2','avax','Avalanche',28,11],['stellar','xlm','Stellar',0.11,3.2],['sui','sui','Sui',1.9,5.5],['the-open-network','ton','Toncoin',5.4,13],['shiba-inu','shib','Shiba Inu',0.000018,10.5],['hedera-hashgraph','hbar','Hedera',0.07,2.7],['litecoin','ltc','Litecoin',70,5.2],['polkadot','dot','Polkadot',5.2,7.4],['uniswap','uni','Uniswap',7.8,4.7],['near','near','NEAR Protocol',5.1,5.4],['aptos','apt','Aptos',8.6,3.9],['pepe','pepe','Pepe',0.0000095,4],['arbitrum','arb','Arbitrum',0.75,2.9],['cosmos','atom','Cosmos Hub',6.6,2.6],['aave','aave','Aave',160,2.4],['filecoin','fil','Filecoin',4.4,2.5],['render-token','render','Render',6.2,3.2],['injective-protocol','inj','Injective',19,1.8],['optimism','op','Optimism',1.7,2.1],['maker','mkr','Maker',1500,1.4],['the-graph','grt','The Graph',0.17,1.6],['algorand','algo','Algorand',0.15,1.2],['bonk','bonk','Bonk',0.000021,1.5],['celestia','tia','Celestia',4.6,1.1],['sei-network','sei','Sei',0.38,1.3],['jupiter-exchange-solana','jup','Jupiter',0.8,1.1],['ondo-finance','ondo','Ondo',0.9,1.3],['worldcoin-wld','wld','Worldcoin',2.1,1.2],['floki','floki','FLOKI',0.00014,1.3],['dai','dai','Dai',1,5.3]];\nfunction makeDemo() {\n  const coins = DEMO_LIST.map((d, i) => {\n    const r = rng(1000 + i * 77), n = 84;\n    const vol = 0.003 + r() * 0.012 + i * 0.0001, drift = (r() - 0.46) * 0.004;\n    const stable = ['usdt','usdc','dai'].includes(d[1]);\n    let v = 1; const raw = [v];\n    for (let k = 1; k < n; k++) { v *= 1 + (stable ? (r() - 0.5) * 0.0004 : drift + (r() - 0.5) * 2 * vol); raw.push(v); }\n    if (i === 22 || i === 33) for (let k = n - 14; k < n; k++) raw[k] *= 1 + (k - (n - 15)) * 0.025;\n    const scale = d[3] / raw[n - 1];\n    const spark = raw.map((x) => Number((x * scale).toPrecision(6)));\n    const last = spark[n - 1], prev = spark[n - 2];\n    return {\n      id: d[0], symbol: d[1], name: d[2], image: '', price: last, mcap: d[4] * 1e9, rank: i + 1,\n      vol: d[4] * 1e9 * (stable ? 0.6 : 0.025 + r() * 0.12),\n      c1h: (last / prev - 1) * 50, c24: (last / spark[n - 13] - 1) * 100, c7: (last / spark[0] - 1) * 100,\n      c30: stable ? 0 : (last / spark[0] - 1) * 100 * (0.8 + r() * 1.6) + (r() - 0.5) * 12,\n      ath: stable ? -0.5 : -(5 + r() * 85), spark,\n    };\n  });\n  const now = Date.now(), H = 3600e3;\n  const news = [\n    ['Örnek başlık: Bitcoin ETF\\'lerine net giriş sürüyor, piyasada iyimserlik artıyor', 1],\n    ['Örnek başlık: Ethereum ağ yükseltmesi için tarih netleşti', 2],\n    ['Örnek başlık: Solana tabanlı büyük bir protokolde güvenlik açığı, hack iddiası inceleniyor', 3],\n    ['Örnek başlık: Düzenleyici kurum bir altcoin borsası hakkında dava açtı', 5],\n    ['Örnek başlık: XRP için kurumsal ortaklık haberi yatırımcıyı hareketlendirdi', 6],\n    ['Örnek başlık: Dogecoin ödemeleri yeni bir platformda kabul edilmeye başlandı', 8],\n    ['Örnek başlık: Piyasalarda belirsizlik, yatırımcılar temkinli', 10],\n    ['Örnek başlık: Chainlink yeni bir kurumsal entegrasyonu duyurdu, LINK toparlanıyor', 12],\n    ['Örnek başlık: Küçük bir meme coin sert çöküş yaşadı, işlem hacmi eridi', 15],\n    ['Örnek başlık: Stablecoin piyasa değeri yeni rekora ulaştı', 20],\n  ].map(([title, h]) => ({ title, link: '', source: 'Örnek', date: now - h * H }));\n  return { coins, news };\n}\nfunction makeDemoEx(coins) {\n  const r = rng(4242), binance = {}, midas = {};\n  coins.forEach((c, i) => {\n    const sym = String(c.symbol).toUpperCase();\n    binance[sym] = { p: c.price * (1 + (r() - 0.5) * 0.002), c: (c.c24 ?? 0) + (r() - 0.5), v: c.vol * 0.3 };\n    if (i < 25) midas[sym] = { slug: c.id, p: c.price * (1 + (r() - 0.5) * 0.004), c: (c.c24 ?? 0) + (r() - 0.5) };\n  });\n  return { updated: Date.now(), binance, midas, ok: { binance: true, midas: true } };\n}\n/* ---- Rehber: tanıtımlar ve uzun açıklamalar ---- */\nconst COIN_INFO = {\n  'bitcoin': 'İlk ve en büyük kripto para. 2009\\'da Satoshi Nakamoto takma adıyla yayımlanan bir belgeyle ortaya çıktı. Toplam arzı 21 milyonla sınırlıdır; bu kıt arz yapısı yüzünden birçok kişi onu \"dijital altın\" olarak görür. Güvenliği madencilik (proof-of-work) ile sağlanır.',\n  'ethereum': 'Akıllı sözleşmeleri çalıştıran en büyük blokzincir. Merkeziyetsiz finans (DeFi), NFT ve birçok uygulama bu ağ üzerinde çalışır. İşlem ücretleri ETH ile ödenir, ağı güvende tutan doğrulayıcılar da ETH\\'i stake eder.',\n  'tether': 'Değerinin 1 ABD dolarına eşit kalması hedeflenen stabil coin (USDT). Borsalarda alım satımda \"dolar yerine\" en çok kullanılan tokendir. Fiyatı neredeyse hiç oynamaz; değeri, ihraç eden şirketin rezervlerine duyulan güvene dayanır.',\n  'ripple': 'Sınır ötesi para transferlerini hızlı ve ucuz yapmak için tasarlanan XRP Ledger\\'ın coini. Ripple şirketiyle yakından anılır; düzenleyici davalar ve kurumsal haberler fiyatını sık etkiler.',\n  'binancecoin': 'Binance borsasının ve BNB Chain ağının coini. Ağ işlem ücretlerinde ve Binance\\'in bazı hizmetlerinde kullanılır.',\n  'solana': 'Hızlı ve düşük ücretli işlem sunmayı hedefleyen blokzincir. Birçok DeFi, NFT ve meme coin projesi Solana üzerinde çalışır.',\n  'usd-coin': 'Dolara sabitlenmiş stabil coin (USDC). Circle şirketi ihraç eder; rezervlerini düzenli olarak açıklamasıyla bilinir.',\n  'dogecoin': '2013\\'te şaka olarak çıkan, köpek maskotlu meme coin. Fiyatı büyük ölçüde sosyal medya ve ünlü kişilerin açıklamalarıyla hareket eder. Arzı sınırlı değildir.',\n  'tron': 'Eğlence ve içerik uygulamaları için kurulan, bugün özellikle USDT transferlerinde yoğun kullanılan blokzincir.',\n  'cardano': 'Akademik araştırmalara dayanarak aşamalı geliştirilen proof-of-stake blokzincir. Geliştirme temposunun yavaşlığı sık eleştirilir.',\n  'chainlink': 'Blokzincir dışındaki gerçek dünya verilerini (fiyat gibi) akıllı sözleşmelere taşıyan \"oracle\" ağı. Birçok DeFi projesi fiyat verisini buradan alır.',\n  'avalanche-2': 'İşlemleri çabuk sonuçlandıran ve özelleştirilebilir alt ağlar (subnet) sunan blokzincir platformu.',\n  'stellar': 'Sınır ötesi ödemeleri hızlı ve ucuz yapmak için tasarlanmış ağ. Bankalar ve ödeme şirketleriyle çalışmaya odaklanır.',\n  'sui': 'Move programlama dilini kullanan yeni nesil bir blokzincir. Yüksek hız ve düşük ücret hedefler.',\n  'the-open-network': 'Telegram ile ilişkili geliştirilen TON blokzinciri. Telegram içindeki mini uygulamalar ve ödemelerle öne çıkar.',\n  'shiba-inu': 'Dogecoin\\'den esinlenen meme coin. Arzı çok büyük olduğu için birim fiyatı çok küçüktür; fiyatı spekülasyona dayanır.',\n  'hedera-hashgraph': 'Klasik blokzincirden farklı \"hashgraph\" teknolojisini kullanan, büyük şirketlerden oluşan bir konsey tarafından yönetilen ağ.',\n  'litecoin': '2011\\'de Bitcoin\\'e daha hızlı ve ucuz bir alternatif olarak çıkan, eski kripto paralardan biri.',\n  'polkadot': 'Farklı blokzincirlerinin birbirine bağlanıp haberleşmesini hedefleyen ağ.',\n  'uniswap': 'Ethereum\\'daki en büyük merkeziyetsiz borsalardan (DEX) birinin yönetim tokenı. Kullanıcılar aracı olmadan token takas eder.',\n  'near': 'Kullanımı kolay olmayı hedefleyen, hızlı ve düşük ücretli blokzincir protokolü.',\n  'aptos': 'Eski Meta (Facebook) Diem projesi çalışanlarının kurduğu, Move dilini kullanan blokzincir.',\n  'pepe': 'Bir internet mizah figürüne dayanan meme coin. Fiyatı neredeyse tamamen spekülasyon ve sosyal medya ilgisiyle hareket eder; çok risklidir.',\n  'arbitrum': 'Ethereum\\'un işlem ücretlerini düşürmeyi ve hızını artırmayı hedefleyen \"katman 2\" ağı.',\n  'cosmos': 'Birbirine bağlanabilen bağımsız blokzincirlerden oluşan \"blokzincirler interneti\" vizyonunun ağı.',\n  'aave': 'Kripto varlıkların ödünç alınıp verilebildiği büyük merkeziyetsiz borç verme protokollerinden biri.',\n  'filecoin': 'Kullanılmayan disk alanını kiralayarak merkeziyetsiz dosya depolama sunan ağ.',\n  'render-token': 'Grafik işlem gücünün (GPU) merkeziyetsiz biçimde kiralandığı ağ. Yapay zekâ ve 3B grafik işlerinde kullanılır.',\n  'injective-protocol': 'Finans uygulamalarına odaklanan, merkeziyetsiz türev piyasaları sunan blokzincir.',\n  'optimism': 'Ethereum\\'un ücretlerini düşüren katman 2 ağı; Arbitrum\\'un rakibi.',\n  'maker': 'DAI stabil coininin arkasındaki merkeziyetsiz borç protokolünün yönetim tokenı.',\n  'the-graph': 'Blokzincir verilerini düzenleyip uygulamaların kolayca sorgulamasını sağlayan indeksleme protokolü.',\n  'algorand': 'Hızlı ve enerji verimli proof-of-stake blokzincir.',\n  'bonk': 'Solana üzerindeki popüler bir meme coin.',\n  'celestia': 'Blokzincirlerin veri kaydı için kullandığı modüler veri erişilebilirlik katmanı.',\n  'sei-network': 'Alım satım uygulamaları için hız odaklı tasarlanmış blokzincir.',\n  'jupiter-exchange-solana': 'Solana\\'daki en çok kullanılan token takas toplayıcısı Jupiter\\'in tokenı.',\n  'ondo-finance': 'ABD Hazine tahvili gibi gerçek dünya varlıklarını zincir üstüne taşıyan (tokenizasyon) proje.',\n  'worldcoin-wld': 'Göz bebeği taramasıyla kişinin \"gerçek insan\" olduğunu kanıtlamayı amaçlayan proje. Gizlilik açısından tartışmalıdır.',\n  'floki': 'Köpek temalı meme coin ve ona bağlı küçük bir ekosistem.',\n  'dai': 'Dolara sabitlenmiş, teminatlı ve merkeziyetsiz stabil coin.',\n  'bitcoin-cash': '2017\\'de Bitcoin\\'den ayrılan, daha büyük blok boyutuyla hızlı ve ucuz ödemeyi hedefleyen coin.',\n  'monero': 'İşlem ayrıntılarını gizleyen, gizlilik odaklı kripto para. Bu özelliği nedeniyle bazı borsalardan çıkarılmıştır.',\n  'ethereum-classic': '2016\\'daki bir saldırıdan sonra Ethereum\\'un ikiye ayrılmasıyla ortaya çıkan, orijinal zinciri sürdüren ağ.',\n  'internet-computer': 'Uygulamaları doğrudan blokzincir üzerinde çalıştırmayı hedefleyen ağ.',\n  'vechain': 'Tedarik zinciri takibi ve kurumsal kullanım odaklı blokzincir.',\n  'stacks': 'Bitcoin üzerinde akıllı sözleşme çalıştırmayı hedefleyen katman.',\n  'lido-dao': 'Ethereum stake etmek isteyenlere karşılığında token veren en büyük stake protokollerinden birinin tokenı.',\n};\nconst SIG_TXT = {\n  'GÜÇLÜ AL': 'Fiyat hareketi ve göstergelerin çoğu aynı yönde olumlu. Bu, yükselişin süreceği anlamına gelmez; yalnızca şu anki tablo taradığımız diğer varlıklara göre güçlü görünüyor.',\n  'AL': 'Göstergelerin çoğu olumlu ama tablo çok güçlü değil. Olumlu işaretler ağır basıyor, yine de olumsuz taraflar da var.',\n  'BEKLE': 'Net bir yön yok: olumlu ve olumsuz işaretler birbirini dengeliyor ya da fiyat yatay seyrediyor. Bu \"sat\" demek değildir; acele edilecek bir neden görünmüyor demektir.',\n  'AZALT': 'Göstergelerde zayıflama var. Olumsuz işaretler olumlulardan fazla, ama trend henüz belirgin biçimde aşağı dönmüş değil.',\n  'SAT': 'Fiyat belirgin biçimde aşağı yönde ve göstergelerin çoğu olumsuz. Düşen fiyatın nerede duracağını bilmek mümkün değil; bu yüzden böyle varlıklara yeni alım yapmak genellikle riskli kabul edilir.',\n};\nfunction rsiText(r) {\n  if (r === null || r === undefined) return null;\n  const v = r.toFixed(0);\n  if (r >= 75) return `RSI göstergesi 0 ile 100 arasında değer alır; 70 üstü \"aşırı alım\", 30 altı \"aşırı satım\" sayılır. Şu an ${v}: fiyat kısa sürede çok hızlı yükselmiş, bu da genellikle bir geri çekilme ihtimalini artırır.`;\n  if (r >= 65) return `RSI göstergesi 0 ile 100 arasında değer alır; 70 üstü \"aşırı alım\", 30 altı \"aşırı satım\" sayılır. Şu an ${v}: aşırı alım bölgesine yakın, yükselişin ivmesi zayıflayabilir.`;\n  if (r <= 30) return `RSI göstergesi 0 ile 100 arasında değer alır; 70 üstü \"aşırı alım\", 30 altı \"aşırı satım\" sayılır. Şu an ${v}: fiyat çok hızlı düşmüş. Bu bazen tepki yükselişine işaret eder, ama düşüş de sürebilir.`;\n  return `RSI göstergesi 0 ile 100 arasında değer alır; 70 üstü \"aşırı alım\", 30 altı \"aşırı satım\" sayılır. Şu an ${v}: normal aralıkta.`;\n}\n\n// Coin için uzun açıklama. fmt: fiyatı biçimlendiren işlev.\nfunction narrateCoin(c, fmt) {\n  fmt = fmt || ((v) => String(v));\n  const a = c.a, st = a.st, sec = [], risks = [];\n  if (a.signal === 'STABİL') {\n    sec.push({ h: 'Nasıl okunmalı?', p: [`${c.name}, değerini bir varlığa (genellikle bir para birimine ya da altına) sabitlemeyi hedefleyen bir token. Fiyatı normalde neredeyse hiç oynamaz, bu yüzden al/sat sinyali üretmiyoruz.`, 'Asıl risk fiyat hareketi değil, ihraççının rezervlerine ve düzenleyici duruma duyulan güvendir. Fiyatın hedefin belirgin biçimde altına düşmesi (depeg) ciddi bir uyarıdır.'] });\n    risks.push('İhraççı şirketin rezerv ve denetim bilgilerini takip edin; fiyat hedefin altına düşerse hemen dikkate alın.', 'Düzenleyici kararlar stabil coinlerin borsalarda işlem görmesini etkileyebilir.');\n    return { sec, risks };\n  }\n  const pos = st && st.hi > st.lo ? (st.last - st.lo) / (st.hi - st.lo) * 100 : null;\n  const ctx = [];\n  ctx.push(`${c.name}, piyasa değerine göre ${c.rank ?? 'sıralamada yer almayan'}${c.rank ? '. sırada' : ''} bir coin. Bu uygulamanın puanı ${a.score}/100, sinyali \"${a.signal}\", risk seviyesi \"${a.risk}\".`);\n  ctx.push(SIG_TXT[a.signal]);\n  if (a.hot) ctx.push('Fiyat çok hızlı yükselmiş olduğu için \"aşırı ısınmış\" olarak işaretlendi. Böyle durumlarda uygulama Al sinyali vermez; yükselişi kovalamak yerine geri çekilmeyi beklemek daha güvenli sayılır.');\n  sec.push({ h: 'Kısa özet', p: ctx });\n\n  const mv = [];\n  mv.push(`Fiyat son 1 saatte ${num(c.c1h) === null ? 'bilinmiyor' : fmtP(c.c1h)}, 24 saatte ${num(c.c24) === null ? 'bilinmiyor' : fmtP(c.c24)}, 7 günde ${num(c.c7) === null ? 'bilinmiyor' : fmtP(c.c7)} ve 30 günde ${num(c.c30) === null ? 'bilinmiyor' : fmtP(c.c30)} değişti.`);\n  if (st) {\n    mv.push(`Son 7 günün en düşük fiyatı ${fmt(st.lo)}, en yükseği ${fmt(st.hi)}. Şu anki fiyat bu aralığın yüzde ${pos.toFixed(0)}'inde (0 aralığın dibi, 100 tepesi). ${pos > 85 ? 'Yani fiyat haftanın zirvesine yakın.' : pos < 15 ? 'Yani fiyat haftanın dibine yakın.' : 'Yani fiyat aralığın ortalarında.'}`);\n    mv.push(`Fiyat 7 günlük ortalamasının yüzde ${f1(st.trend)} ${st.trend >= 0 ? 'üstünde' : 'altında'}. ${Math.abs(st.trend) < 3 ? 'Bu, kısa vadede belirgin bir yön olmadığını gösterir.' : st.trend > 0 ? 'Fiyat ortalamanın üstünde kalmaya devam ettikçe kısa vadeli eğilim yukarı sayılır.' : 'Fiyat ortalamanın altında kaldıkça kısa vadeli eğilim aşağı sayılır.'}`);\n  }\n  if (num(c.ath) !== null) mv.push(`Tüm zamanların en yüksek fiyatının yüzde ${f1(c.ath)} ${c.ath < 0 ? 'altında' : 'üstünde'}. ${c.ath < -80 ? 'Zirveden bu kadar uzak olmak, toparlanmanın uzun sürebileceğini gösterir.' : ''}`.trim());\n  sec.push({ h: 'Fiyat hareketi', p: mv });\n\n  const ind = [];\n  const rt = st && rsiText(st.rsi); if (rt) ind.push(rt);\n  if (a.vol !== null && a.vol !== undefined) ind.push(`Günlük ortalama dalgalanma yaklaşık yüzde ${f1(a.vol)}. Bu coin için gün içinde fiyatın bu kadar oynaması sıradan sayılır; yüzde ${f1(a.vol * 2)} civarı hareketler de nadir değildir.`);\n  if (a.liq) ind.push(`Son 24 saatteki işlem hacmi piyasa değerinin yüzde ${f1(a.liq * 100)}'i. ${a.liq < 0.02 ? 'Bu düşük bir oran: alım satım yapmak isteyen az olduğu için büyük emirlerde fiyat kayabilir.' : a.liq > 0.08 ? 'Bu yüksek bir oran: coin aktif işlem görüyor.' : 'Bu normal bir seviye.'}`);\n  if (ind.length) sec.push({ h: 'Göstergeler', p: ind });\n\n  const nw = [];\n  if (a.hits && a.hits.length) {\n    nw.push(`Taradığımız haber kaynaklarında bu coinle ilgili ${a.hits.length} başlık var. En yeni başlık: \"${a.hits[0].title}\" (${a.hits[0].source}).`);\n    const avgS = avg(a.hits.map((h) => h.score));\n    nw.push(avgS > 0.3 ? 'Başlıkların genel tonu olumlu.' : avgS < -0.3 ? 'Başlıkların genel tonu olumsuz.' : 'Başlıkların tonu nötr.');\n  } else nw.push('Taradığımız haber kaynaklarında bu coinle ilgili başlık bulunmuyor. Bu, haber akışının puana katkısının sıfır olduğu anlamına gelir.');\n  nw.push('Haber tonu, başlıklardaki kelimelere bakan basit bir taramayla ölçülür; haberin içeriğini anlayarak okumaz.');\n  sec.push({ h: 'Haberler', p: nw });\n\n  if (a.risk === 'Yüksek') risks.push('Risk seviyesi yüksek: fiyat çok sert dalgalanabilir veya coin küçük bir piyasa değerine sahip.');\n  if (a.hot) risks.push('Fiyat kısa sürede çok yükseldi. Böyle yükselişlerin ardından sert düşüş sık görülür.');\n  if (a.liq !== null && a.liq !== undefined && a.liq < 0.02) risks.push('İşlem hacmi düşük: istediğiniz anda istediğiniz fiyattan satamayabilirsiniz.');\n  if ((c.rank || 9999) > 200) risks.push('Piyasa değeri küçük bir coin. Küçük coinler az bir parayla bile sert hareket eder ve manipülasyona daha açıktır.');\n  if (num(c.c24) !== null && c.c24 < -10) risks.push('Son 24 saatte sert düştü; düşüş devam edebilir.');\n  if (a.hits && a.hits.length && avg(a.hits.map((h) => h.score)) < -0.3) risks.push('Haberlerde olumsuz söz ediliyor; başlıkların kendisini okuyup doğrulayın.');\n  risks.push('Kripto piyasası hafta sonu dahil 7/24 açıktır; fiyat siz uyurken de değişir.', 'Puan yalnızca geçmiş fiyat hareketine ve haber başlıklarına bakar. Projenin ekibini, teknolojisini ya da yasal durumunu değerlendirmez.', 'Kaybetmeyi göze alabileceğinizden fazlasını yatırmayın. Tek bir coine büyük tutar bağlamak riski artırır.');\n  return { sec, risks };\n}\n\n/* ---- Hisse analizi (günlük kapanış serisiyle) ---- */\nfunction stockStats(cl) {\n  if (!cl || cl.length < 22 || cl.some((v) => !(v > 0))) return null;\n  const n = cl.length, last = cl[n - 1];\n  const ret = (k) => (n > k ? (last / cl[n - 1 - k] - 1) * 100 : null);\n  const rets = []; for (let i = 1; i < n; i++) rets.push(Math.log(cl[i] / cl[i - 1]));\n  const r = rets.slice(-60), mu = avg(r), sd = Math.sqrt(avg(r.map((x) => (x - mu) ** 2)));\n  const w = cl.slice(-63);\n  return { last, c1: ret(1), c5: ret(5), c21: ret(21), c63: ret(63), trend: (last / avg(cl.slice(-20)) - 1) * 100, vol: sd * 100, rsi: rsi14(cl.slice(-60)), hi: Math.max(...w), lo: Math.min(...w), dd: (last / Math.max(...cl) - 1) * 100 };\n}\nfunction analyzeStock(cl, liveC, hits, mkt) {\n  hits = hits || []; mkt = mkt || 0;\n  const st = stockStats(cl);\n  if (!st) return { hits, signal: 'VERİ YOK', cls: 's-stable', score: 0, risk: null, reasons: [{ pos: null, t: 'Geçmiş fiyat verisi alınamadığı için bu hisse için puan hesaplanamadı. Canlı fiyat ve Midas bağlantısı yine de gösteriliyor.' }], st: null };\n  const c1 = num(liveC) ?? st.c1, c5 = st.c5 ?? 0, c21 = st.c21 ?? 0;\n  const R = []; let score = 0;\n  score += clamp(c5, -8, 8) / 8 * 25;\n  if (c5 >= 4) R.push({ pos: true, t: `Son 5 işlem gününde ${fmtP(c5)}: yukarı yönlü haftalık hareket.` });\n  else if (c5 <= -4) R.push({ pos: false, t: `Son 5 işlem gününde ${fmtP(c5)}: aşağı yönlü haftalık hareket.` });\n  else R.push({ pos: null, t: `Son 5 işlem gününde ${fmtP(c5)}: sakin seyir.` });\n  score += clamp(c21, -20, 20) / 20 * 25;\n  if (c21 >= 8) R.push({ pos: true, t: `Son bir ayda ${fmtP(c21)}: aylık trend yukarı.` });\n  else if (c21 <= -8) R.push({ pos: false, t: `Son bir ayda ${fmtP(c21)}: aylık trend aşağı.` });\n  score += clamp(c1 ?? 0, -4, 4) / 4 * 10;\n  score += clamp(st.trend, -6, 6) / 6 * 10;\n  if (st.trend > 3) R.push({ pos: true, t: `Fiyat 20 günlük ortalamasının %${f1(st.trend)} üstünde.` });\n  else if (st.trend < -3) R.push({ pos: false, t: `Fiyat 20 günlük ortalamasının %${f1(st.trend)} altında.` });\n  if (st.rsi !== null) {\n    if (st.rsi >= 75) { score -= 15; R.push({ pos: false, t: `RSI ${st.rsi.toFixed(0)}: aşırı alım bölgesi, geri çekilme riski yüksek.` }); }\n    else if (st.rsi >= 65) { score -= 5; R.push({ pos: false, t: `RSI ${st.rsi.toFixed(0)}: alım bölgesi sınırında.` }); }\n    else if (st.rsi >= 45) score += 5;\n    else if (st.rsi <= 30) { score += 8; R.push({ pos: true, t: `RSI ${st.rsi.toFixed(0)}: aşırı satım bölgesi, tepki yükselişi ihtimali var (düşüş sürebilir).` }); }\n  }\n  if (hits.length) {\n    const av = avg(hits.map((h) => h.score));\n    score += clamp(av * 5, -10, 10);\n    if (av > 0.3) R.push({ pos: true, t: `Haberlerde olumlu söz edilmiş (${hits.length} başlık).` });\n    else if (av < -0.3) R.push({ pos: false, t: `Haberlerde olumsuz söz edilmiş (${hits.length} başlık).` });\n    else R.push({ pos: null, t: `Haberlerde geçiyor (${hits.length} başlık), tonu nötr.` });\n  }\n  score += clamp(mkt * 5, -5, 5);\n  if (mkt > 0.3) R.push({ pos: true, t: 'Genel haber akışı olumlu.' });\n  else if (mkt < -0.3) R.push({ pos: false, t: 'Genel haber akışı olumsuz.' });\n  const hot = (c1 ?? 0) > 8 || c21 > 35 || (st.rsi !== null && st.rsi >= 75);\n  if ((c1 ?? 0) > 8) { score -= 12; R.push({ pos: false, t: `Bugün ${fmtP(c1)} sıçradı. Ani sıçramaların ardından geri çekilme sık görülür.` }); }\n  if (st.dd < -25) R.push({ pos: null, t: `Son 6 ayın zirvesinin %${f1(st.dd)} altında.` });\n  score = Math.round(clamp(score, -100, 100));\n  let signal, cls;\n  if (score >= 45) { signal = 'GÜÇLÜ AL'; cls = 's-strongbuy'; }\n  else if (score >= 20) { signal = 'AL'; cls = 's-buy'; }\n  else if (score > -10) { signal = 'BEKLE'; cls = 's-hold'; }\n  else if (score > -30) { signal = 'AZALT'; cls = 's-reduce'; }\n  else { signal = 'SAT'; cls = 's-sell'; }\n  if (hot && score >= 20) { signal = 'BEKLE'; cls = 's-hold'; R.unshift({ pos: false, t: 'Aşırı ısınma nedeniyle sinyal \"bekle\" seviyesine çekildi.' }); }\n  const risk = st.vol > 3.5 ? 'Yüksek' : st.vol > 2 ? 'Orta' : 'Düşük';\n  R.push({ pos: null, t: `Günlük ortalama dalgalanma yaklaşık %${f1(st.vol)}; risk seviyesi ${risk.toLowerCase()}.` });\n  return { signal, cls, score, risk, reasons: R, st, hot, c1, hits };\n}\nfunction narrateStock(s, a, fmt) {\n  fmt = fmt || ((v) => String(v));\n  const st = a.st, sec = [], risks = [];\n  if (!st) {\n    sec.push({ h: 'Kısa özet', p: [`${s.n} için geçmiş fiyat verisi alınamadı, bu yüzden puan ve ayrıntılı analiz üretemiyoruz. Hissenin ne iş yaptığını yukarıda okuyabilir, canlı fiyatı ve Midas bağlantısını aşağıda görebilirsiniz.`] });\n  } else {\n    sec.push({ h: 'Kısa özet', p: [`${s.n} (${s.s}) için bu uygulamanın puanı ${a.score}/100, sinyali \"${a.signal}\", risk seviyesi \"${a.risk}\".`, SIG_TXT[a.signal], ...(a.hot ? ['Fiyat kısa sürede çok yükseldiği için \"aşırı ısınmış\" olarak işaretlendi ve Al sinyali verilmedi.'] : [])] });\n    const pos = st.hi > st.lo ? (st.last - st.lo) / (st.hi - st.lo) * 100 : 50;\n    sec.push({ h: 'Fiyat hareketi', p: [\n      `Bir önceki işlem gününe göre ${fmtP(a.c1 ?? 0)}, son 5 işlem gününde ${st.c5 === null ? 'bilinmiyor' : fmtP(st.c5)}, son bir ayda ${st.c21 === null ? 'bilinmiyor' : fmtP(st.c21)}${st.c63 !== null ? ' ve son üç ayda ' + fmtP(st.c63) : ''} değişti.`,\n      `Son üç ayın en düşük kapanışı ${fmt(st.lo)}, en yükseği ${fmt(st.hi)}. Şu anki fiyat bu aralığın yüzde ${pos.toFixed(0)}'inde. ${pos > 85 ? 'Yani fiyat üç aylık zirveye yakın.' : pos < 15 ? 'Yani fiyat üç aylık dibe yakın.' : 'Yani fiyat aralığın ortalarında.'}`,\n      `Fiyat 20 günlük ortalamasının yüzde ${f1(st.trend)} ${st.trend >= 0 ? 'üstünde' : 'altında'}.`,\n    ] });\n    const ind = []; const rt = rsiText(st.rsi); if (rt) ind.push(rt);\n    ind.push(`Günlük ortalama dalgalanma yaklaşık yüzde ${f1(st.vol)}. Bu hisse için gün içinde fiyatın bu kadar oynaması sıradan sayılır.`);\n    sec.push({ h: 'Göstergeler', p: ind });\n    const nw = [];\n    if (a.hits && a.hits.length) { nw.push(`Taradığımız haber kaynaklarında bu şirketle ilgili ${a.hits.length} başlık var. En yeni başlık: \"${a.hits[0].title}\" (${a.hits[0].source}).`); const avS = avg(a.hits.map((h) => h.score)); nw.push(avS > 0.3 ? 'Başlıkların genel tonu olumlu.' : avS < -0.3 ? 'Başlıkların genel tonu olumsuz.' : 'Başlıkların tonu nötr.'); }\n    else nw.push('Taradığımız haber kaynaklarında bu şirketle ilgili başlık bulunmuyor; haber akışının puana katkısı sıfır.');\n    sec.push({ h: 'Haberler', p: nw });\n    if (a.risk === 'Yüksek') risks.push('Günlük dalgalanma yüksek: fiyat kısa sürede sert değişebilir.');\n    if (a.hot) risks.push('Fiyat kısa sürede çok yükseldi; sert yükselişlerin ardından geri çekilme sık görülür.');\n    if (st.dd < -25) risks.push(`Hisse son 6 ayın zirvesinin %${f1(st.dd)} altında; düşüş trendi sürebilir.`);\n  }\n  risks.push('Hisse fiyatları yalnızca borsanın açık olduğu saatlerde oluşur. Kapanıştan sonraki haberler ertesi gün fiyata açılışta sert yansıyabilir.', 'Puan yalnızca geçmiş fiyat hareketine bakar. Şirketin bilançosunu, borcunu, sektörünü ve haberlerini değerlendirmez.', 'Midas\\'ta gösterilen canlı fiyatlar gecikmeli olabilir (BIST için yaklaşık 15 dakika). İşlem yapmadan önce uygulamadaki güncel fiyatı kontrol edin.', 'Kaybetmeyi göze alabileceğinizden fazlasını yatırmayın.');\n  return { sec, risks };\n}\nfunction buildStockWorld(stocks, news) {\n  const items = [];\n  for (const k of ['us', 'bist', 'eu']) (stocks.meta[k] || []).forEach((m, i) => {\n    const lv = stocks[k] && stocks[k][m.s], h = stocks.hist && stocks.hist[k] && stocks.hist[k][m.s];\n    items.push({ id: k + ':' + m.s, kind: 'stock', mk: k, symbol: m.s, name: m.n, alias: m.al || [], sector: m.k, desc: m.d, dom: m.dom || '', rank: i + 1, cur: k === 'us' ? 'USD' : k === 'bist' ? 'TRY' : 'EUR', h, lv });\n  });\n  const ctx = newsContext(news, items);\n  for (const it of items) {\n    const hits = ctx.byCoin[it.id] || [];\n    const a = analyzeStock(it.h, it.lv ? it.lv.c : null, hits, ctx.market);\n    it.a = a; it.live = !!it.lv;\n    it.price = it.lv ? it.lv.p : (it.h ? it.h[it.h.length - 1] : null);\n    it.c24 = it.lv && num(it.lv.c) !== null ? it.lv.c : (a.st ? a.st.c1 : null);\n    it.c7 = a.st ? a.st.c5 : null; it.c30 = a.st ? a.st.c21 : null; it.c1h = null;\n    it.spark = it.h ? it.h.slice(-63) : [];\n  }\n  const scored = items.filter((x) => x.a.st);\n  const m = scored.length ? avg(scored.map((x) => x.a.score)) : 0;\n  const tally = { buy: 0, hold: 0, sell: 0 };\n  for (const x of scored) { if (x.a.signal === 'GÜÇLÜ AL' || x.a.signal === 'AL') tally.buy++; else if (x.a.signal === 'BEKLE') tally.hold++; else tally.sell++; }\n  return { items, info: { ctx, mood: moodLabel(m), moodScore: m, tally, analyzed: scored.length } };\n}\nfunction makeDemoStockNews() {\n  const now = Date.now(), H = 3600e3;\n  return [['Örnek başlık: Apple yeni ürün tanıtımı öncesi yatırımcı ilgisi artıyor', 1], ['Örnek başlık: Nvidia için analistler hedef fiyatını yükseltti', 3], ['Örnek başlık: Türk Hava Yolları yaz sezonunda yolcu rekoru bekliyor', 4], ['Örnek başlık: Aselsan yeni savunma sözleşmesi imzaladı, hisse yükseldi', 6], ['Örnek başlık: Piyasalarda faiz kararı öncesi temkinli seyir', 8], ['Örnek başlık: Coca-Cola çeyrek kârını açıkladı', 12]]\n    .map(([title, h]) => ({ title, link: '', source: 'Örnek', date: now - h * H }));\n}\nfunction makeDemoStocks() {\n  const mk = (seed, base, drift) => { const r = rng(seed); let v = base; const a = []; for (let i = 0; i < 126; i++) { v *= 1 + drift + (r() - 0.5) * 0.03; a.push(Number(v.toPrecision(6))); } return a; };\n  const meta = {\n    us: [['AAPL', 'Apple', 'Teknoloji', 'iPhone, Mac ve iPad üreten teknoloji şirketi.'], ['NVDA', 'Nvidia', 'Yarı iletken', 'Grafik işlemci üreticisi; yapay zeka haberlerine duyarlıdır.'], ['KO', 'Coca-Cola', 'Gıda / İçecek', 'Dünyanın en büyük içecek markalarından biri.']],\n    bist: [['THYAO', 'Türk Hava Yolları', 'Ulaşım', 'Türkiye\\'nin bayrak taşıyıcı havayolu şirketi.'], ['ASELS', 'Aselsan', 'Savunma', 'Savunma elektroniği alanında büyük şirket.'], ['BIMAS', 'BİM Mağazalar', 'Perakende', 'Büyük indirim marketi zinciri.']],\n  };\n  const doms = { AAPL: 'apple.com', NVDA: 'nvidia.com', KO: 'coca-colacompany.com', THYAO: 'turkishairlines.com', ASELS: 'aselsan.com', BIMAS: 'bim.com.tr' };\n  const m = (l) => l.map(([s, n, k, d]) => ({ s, n, k, d, dom: doms[s], al: s === 'THYAO' ? ['Turkish Airlines'] : [] }));\n  const hist = { us: { AAPL: mk(11, 180, 0.001), NVDA: mk(12, 120, 0.003), KO: mk(13, 60, 0) }, bist: { THYAO: mk(14, 280, 0.002), ASELS: mk(15, 90, 0.004), BIMAS: mk(16, 500, -0.001) } };\n  const live = (h) => Object.fromEntries(Object.entries(h).map(([k, v]) => [k, { p: v[v.length - 1], c: (v[v.length - 1] / v[v.length - 2] - 1) * 100 }]));\n  return { updated: Date.now(), meta: { us: m(meta.us), bist: m(meta.bist) }, us: live(hist.us), bist: live(hist.bist), hist, ok: { midas: true, hist: true } };\n}\n/* ---- Portföy (saf hesaplar; arayüzden bağımsız) ---- */\n// Türkçe ya da İngilizce yazılmış sayıyı okur: \"0,05\", \"0.05\", \"3.183.256,96\". Boş ya da bozuksa null.\nfunction parseNumTr(s) {\n  s = String(s === null || s === undefined ? '' : s).trim().replace(/[\\s₺$€]/g, '');\n  if (!s) return null;\n  if (s.includes(',') && s.includes('.')) s = s.lastIndexOf(',') > s.lastIndexOf('.') ? s.replace(/\\./g, '').replace(',', '.') : s.replace(/,/g, '');\n  else if (s.includes(',')) s = s.replace(',', '.');\n  else if ((s.match(/\\./g) || []).length > 1) s = s.replace(/\\./g, '');\n  else if (/^[1-9]\\d{0,2}\\.\\d{3}$/.test(s)) s = s.replace('.', ''); // \"10.000\": Türkçe yazımda binlik ayracı\n  if (!/^\\d*\\.?\\d+$|^\\d+\\.$/.test(s)) return null;\n  const n = Number(s);\n  return Number.isFinite(n) && n >= 0 ? n : null;\n}\n// Yazılan sayıya binlik noktası koyar, ondalık için virgülü korur: \"1234567,5\" → \"1.234.567,5\". Rakam ve virgül dışını atar.\nfunction groupNum(s) {\n  s = String(s === null || s === undefined ? '' : s).replace(/[^\\d,]/g, '');\n  const i = s.indexOf(',');\n  const ip = (i < 0 ? s : s.slice(0, i)).replace(/^0+(?=\\d)/, '').replace(/\\B(?=(\\d{3})+(?!\\d))/g, '.');\n  return i < 0 ? ip : ip + ',' + s.slice(i + 1).replace(/,/g, '');\n}\n// Kayıtlı ya da hesaplanmış bir sayıyı alana yazılacak biçime çevirir (binlik noktalı, ondalık virgüllü). Okunamazsa boş.\nfunction numField(v) {\n  const n = typeof v === 'number' ? v : parseNumTr(v);\n  return n === null || n === undefined || !Number.isFinite(n) ? '' : groupNum(n.toLocaleString('en-US', { useGrouping: false, maximumFractionDigits: 10 }).replace('.', ','));\n}\n// Portföyü tek satırlık koda çevirir (bağlantıya ya da kopyala-yapıştır koduna konur).\nfunction portEncode(list) {\n  const rows = list.map((h) => [h.kind === 'coin' ? 'c' : h.kind === 'fx' ? 'f' : 's', h.id, h.sym, h.name, h.qty, h.cost === undefined ? null : h.cost, h.ccy, h.src || '', h.est ? 1 : 0, Array.isArray(h.tx) && h.tx.length ? h.tx.map((x) => [x.t, x.q, num(x.p), x.d || '']) : 0, h.grp || '']);\n  return btoa(unescape(encodeURIComponent(JSON.stringify(rows)))).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/, '');\n}\nfunction portDecode(code) {\n  try {\n    let t = String(code || '').trim();\n    const i = t.indexOf('#p='); if (i >= 0) t = t.slice(i + 3);\n    t = t.replace(/^kp1\\./, '').replace(/\\s+/g, '').replace(/-/g, '+').replace(/_/g, '/');\n    while (t.length % 4) t += '=';\n    const rows = JSON.parse(decodeURIComponent(escape(atob(t))));\n    if (!Array.isArray(rows)) return null;\n    const out = [], stamp = Date.now().toString(36);\n    for (const r of rows.slice(0, 200)) {\n      if (!Array.isArray(r)) continue;\n      const [k, id, sym, name, qty, cost, ccy, src, est, txr, grp] = r;\n      let tx = null;\n      if (Array.isArray(txr)) tx = txr.slice(0, 300).map((x) => (Array.isArray(x) && (x[0] === 'b' || x[0] === 's') && typeof x[1] === 'number' && x[1] > 0 ? { t: x[0], q: x[1], p: typeof x[2] === 'number' && x[2] >= 0 ? x[2] : null, d: String(x[3] || '').slice(0, 10) || null } : null));\n      if (tx && (tx.includes(null) || !txApply(tx).ok)) tx = null;\n      if ((k !== 'c' && k !== 's' && k !== 'f') || typeof id !== 'string' || !id || !(tx || (typeof qty === 'number' && qty > 0 && isFinite(qty)))) continue;\n      const h = { u: 'h' + stamp + out.length, kind: k === 'c' ? 'coin' : k === 'f' ? 'fx' : 'stock', id: id.slice(0, 80), sym: String(sym || '').slice(0, 15), name: String(name || '').slice(0, 60), qty,\n        cost: typeof cost === 'number' && isFinite(cost) && cost >= 0 ? cost : null, ccy: ['TRY', 'USD', 'EUR'].includes(ccy) ? ccy : 'TRY', src: String(src || '').slice(0, 20), est: !!est };\n      if (typeof grp === 'string' && grp.trim()) h.grp = grp.trim().slice(0, 20);\n      if (tx) txCommit(h, tx);\n      out.push(h);\n    }\n    return out;\n  } catch (e) { return null; }\n}\n// Tek bir varlık: değer, maliyet, kâr/zarar, günlük değişimin TL/$/€ karşılığı. Eksik veri null kalır, uydurulmaz.\nfunction portCalc(h, it) {\n  const cur = h.kind === 'coin' ? 'TRY' : (it && it.cur) || h.ccy || 'TRY';\n  const price = it && num(it.price) !== null ? it.price : null;\n  const value = price === null ? null : h.qty * price;\n  const cost = num(h.cost) === null ? null : h.qty * h.cost;\n  const pl = value !== null && cost !== null ? value - cost : null;\n  const plp = pl !== null && cost > 0 ? (pl / cost) * 100 : null;\n  const c24 = it ? num(it.c24) : null;\n  const day = value !== null && c24 !== null ? value - value / (1 + c24 / 100) : null;\n  return { cur, price, value, cost, pl, plp, day, c24 };\n}\n// Para birimine göre toplamlar (kur çevirmeden: TL, $ ve € ayrı ayrı gösterilir).\nfunction portSummary(rows) {\n  const g = {};\n  for (const r of rows) {\n    const x = g[r.c.cur] || (g[r.c.cur] = { cur: r.c.cur, value: 0, costKnown: 0, valueKnown: 0, day: 0, hasDay: false, n: 0, noCost: 0, noPrice: 0, parts: [] });\n    x.n++;\n    if (r.c.value === null) { x.noPrice++; continue; }\n    x.value += r.c.value; x.parts.push({ id: r.h.id, sym: r.h.sym, v: r.c.value });\n    if (r.c.day !== null) { x.day += r.c.day; x.hasDay = true; }\n    if (r.c.cost === null) x.noCost++; else { x.costKnown += r.c.cost; x.valueKnown += r.c.value; }\n  }\n  for (const x of Object.values(g)) { x.pl = x.costKnown > 0 ? x.valueKnown - x.costKnown : null; x.plp = x.costKnown > 0 ? (x.pl / x.costKnown) * 100 : null; }\n  return Object.values(g).sort((a, b) => (a.cur === 'TRY' ? -1 : 0) - (b.cur === 'TRY' ? -1 : 0) || b.n - a.n);\n}\n/* ---- Kur, portföy grafiği, haberler, sinyal değişimi ---- */\n// fx: { USD: 1 dolar kaç lira, EUR: 1 euro kaç lira }. Kur yoksa null döner, uydurulmaz.\nfunction fxConv(v, from, to, fx) {\n  if (v === null || v === undefined) return null;\n  if (from === to) return v;\n  const a = from === 'TRY' ? 1 : fx && fx[from], b = to === 'TRY' ? 1 : fx && fx[to];\n  return a > 0 && b > 0 ? (v * a) / b : null;\n}\nfunction portGrand(groups, fx, target) {\n  let value = 0, day = 0, hasDay = false;\n  for (const g of groups) {\n    const v = fxConv(g.value, g.cur, target, fx); if (v === null) return null;\n    value += v;\n    if (g.hasDay) { day += fxConv(g.day, g.cur, target, fx); hasDay = true; }\n  }\n  return { value, day, hasDay, cur: target };\n}\n// Bugünkü miktarlar sabit kabul edilerek, fiyat çizgilerinden portföy değerinin geçmişi.\nfunction portSeries(rows, fx, target) {\n  const list = [];\n  for (const r of rows) {\n    const it = r.it, sp = it && it.spark;\n    if (!sp || sp.length < 8) continue;\n    const k = fxConv(1, r.c.cur, target, fx); if (k === null) continue;\n    list.push({ q: r.h.qty, k, sp });\n  }\n  if (!list.length) return null;\n  const n = Math.min(...list.map((x) => x.sp.length)), values = Array(n).fill(0);\n  for (const x of list) { const off = x.sp.length - n; for (let i = 0; i < n; i++) values[i] += x.q * x.sp[off + i] * x.k; }\n  return { values, used: list.length, total: rows.length };\n}\n// Elindeki varlıklarla ilgili haberler (aynı haber birden çok varlığa aitse etiketler birleşir).\nfunction portNews(rows) {\n  const out = [], idx = new Map();\n  for (const r of rows) for (const n of ((r.it && r.it.a && r.it.a.hits) || [])) {\n    const k = n.link || n.title, tag = String(r.h.sym).toUpperCase();\n    if (idx.has(k)) { const o = idx.get(k); if (!o.tags.includes(tag)) o.tags.push(tag); continue; }\n    const o = { ...n, tags: [tag] }; idx.set(k, o); out.push(o);\n  }\n  return out.sort((a, b) => b.date - a.date);\n}\nconst SIG_RANK = { 'GÜÇLÜ AL': 2, 'AL': 1, 'BEKLE': 0, 'AZALT': -1, 'SAT': -2 };\nfunction portSignals(rows) {\n  const o = {};\n  for (const r of rows) if (r.it && r.it.a && SIG_RANK[r.it.a.signal] !== undefined) o[r.h.id] = r.it.a.signal;\n  return o;\n}\n// Önceki ve şimdiki sinyaller arasındaki değişimler; worse = sinyal kötüleşti.\nfunction sigChanges(prev, cur) {\n  const out = [];\n  for (const id of Object.keys(cur || {})) {\n    const a = prev && prev[id], b = cur[id];\n    if (a && a !== b && SIG_RANK[a] !== undefined) out.push({ id, from: a, to: b, worse: SIG_RANK[b] < SIG_RANK[a] });\n  }\n  return out;\n}\n\n/* ---- Sinyal karnesi: geçmişte verilen sinyallerden sonra fiyat ne yapmış? ---- */\nconst btNew = () => ({ al: [], bekle: [], sat: [], all: [] });\nconst btBucket = (s) => (s === 'GÜÇLÜ AL' || s === 'AL' ? 'al' : s === 'BEKLE' ? 'bekle' : s === 'AZALT' || s === 'SAT' ? 'sat' : null);\n// Hisse: günlük kapanışlar, h iş günü sonrasına bakılır. Analiz o günkü veriyle, geleceği görmeden yapılır.\nfunction btStock(cl, store, h) {\n  h = h || 5;\n  for (let t = 30; t + h < cl.length; t++) {\n    const b = btBucket(analyzeStock(cl.slice(0, t + 1), null, [], 0).signal); if (!b) continue;\n    const f = (cl[t + h] / cl[t] - 1) * 100;\n    store[b].push(f); store.all.push(f);\n  }\n}\n// Coin: 2 saatte bir kapanışlar (84 nokta = 7 gün), h nokta sonrasına bakılır (varsayılan 7 gün).\nfunction btCoin(sp, meta, store, h) {\n  h = h || 84;\n  const ctx = { byCoin: {}, market: 0 };\n  for (let k = 360; k + h < sp.length; k += 12) {\n    const c = { ...meta, price: sp[k], spark: sp.slice(k - 84, k + 1), c1h: null, c24: (sp[k] / sp[k - 12] - 1) * 100, c7: (sp[k] / sp[k - 84] - 1) * 100, c30: (sp[k] / sp[k - 360] - 1) * 100 };\n    const b = btBucket(analyze(c, ctx).signal); if (!b) continue;\n    const f = (sp[k + h] / sp[k] - 1) * 100;\n    store[b].push(f); store.all.push(f);\n  }\n}\nfunction btSummary(st) {\n  const f = (a) => (a.length ? { n: a.length, avg: avg(a), up: (a.filter((x) => x > 0).length / a.length) * 100 } : { n: 0, avg: null, up: null });\n  const r = { al: f(st.al), bekle: f(st.bekle), sat: f(st.sat), all: f(st.all) };\n  const MIN = 30, GAP = 0.5;\n  // al: iyi = ortalamadan belirgin yüksek; sat: iyi = ortalamadan belirgin düşük (yani çıkmak haklı çıkmış)\n  const al = r.al.n < MIN ? 'az' : r.al.avg > r.all.avg + GAP && r.al.up >= r.all.up ? 'iyi' : r.al.avg < r.all.avg - GAP ? 'ters' : 'fark';\n  const sat = r.sat.n < MIN ? 'az' : r.sat.avg < r.all.avg - GAP ? 'iyi' : r.sat.avg > r.all.avg + GAP ? 'ters' : 'fark';\n  return { r, al, sat };\n}\n/* ---- İşlem kaydı: alış/satışlardan miktar, ortalama maliyet ve gerçekleşen kâr/zarar ---- */\n// tx: [{ t: 'b' | 's', q, p (birim fiyat, bilinmiyorsa null), d (tarih) }]. Ortalama maliyet yöntemi:\n// alışlar ortalamayı günceller; satış, o anki ortalama maliyetten düşer ve (satış fiyatı - ortalama) kadar kâr/zarar doğurur.\nfunction txApply(tx) {\n  let q = 0, unk = 0, cost = 0, real = 0, realAny = false, partial = false;\n  for (const x of tx) {\n    if (!(x.q > 0)) return { ok: false, err: 'Miktar sıfırdan büyük olmalı.' };\n    if (x.t === 'b') { q += x.q; if (num(x.p) === null) unk += x.q; else cost += x.q * x.p; continue; }\n    if (x.q > q + 1e-9) return { ok: false, err: 'Elindeki miktardan fazlasını satamazsın.' };\n    const f = q > 0 ? Math.min(1, x.q / q) : 0, known = q - unk, knownSold = known * f;\n    if (known > 1e-12 && num(x.p) !== null) { real += knownSold * (x.p - cost / known); realAny = true; }\n    if (unk > 1e-12 && f > 0) partial = true; // maliyeti bilinmeyen kısım satıldıysa kâr/zarar eksik kalır\n    unk -= unk * f; cost -= cost * f; q -= x.q;\n    if (q < 1e-12) { q = 0; unk = 0; cost = 0; }\n  }\n  return { ok: true, qty: q, cost: q > 0 && unk < 1e-9 && cost >= 0 && q > 0 ? cost / q : null, real: realAny ? real : null, partial };\n}\nconst txOpening = (h) => (h.qty > 0 ? [{ t: 'b', q: h.qty, p: num(h.cost), d: null }] : []);\n// Kayda işlem ekler / siler; geçerliyse h.qty, h.cost, h.real güncellenir. Hata varsa metni döner, kayıt değişmez.\nfunction txCommit(h, tx) {\n  const r = txApply(tx); if (!r.ok) return r.err;\n  h.tx = tx; h.qty = r.qty; h.cost = r.cost; h.real = r.real; h.realPartial = !!r.partial;\n  return null;\n}\nfunction txAdd(h, x) { return txCommit(h, [...(Array.isArray(h.tx) && h.tx.length ? h.tx : txOpening(h)), x]); }\nfunction txRemove(h, i) { const tx = (h.tx || []).filter((_, k) => k !== i); return tx.length ? txCommit(h, tx) : txCommit(h, txOpening({ qty: 0 })) || null; }\n// Para birimine göre satışlardan gerçekleşen kâr/zarar toplamı\nfunction portRealized(list) {\n  const g = {};\n  for (const h of list) if (num(h.real) !== null) { const c = h.kind === 'coin' ? 'TRY' : h.ccy || 'TRY'; g[c] = (g[c] || 0) + h.real; }\n  return g;\n}\n/* ---- Dağılım uyarısı ve haftalık özet ---- */\n// En büyük varlığın portföydeki payı (ortak para biriminde). Kur gerekip yoksa null.\nfunction portConc(rows, fx, target) {\n  const list = [];\n  for (const r of rows) {\n    if (r.c.value === null) continue;\n    const v = fxConv(r.c.value, r.c.cur, target, fx); if (v === null) return null;\n    list.push({ sym: r.h.sym, v });\n  }\n  if (list.length < 2) return null;\n  list.sort((a, b) => b.v - a.v);\n  const tot = list.reduce((s, x) => s + x.v, 0); if (!(tot > 0)) return null;\n  return { sym: list[0].sym, share: (list[0].v / tot) * 100, top2: ((list[0].v + list[1].v) / tot) * 100, n: list.length };\n}\n// Son 1 hafta: coinde 7 gün, hissede 5 işlem günü. Bugünkü miktarlar sabit kabul edilir.\nfunction portWeek(rows, fx, target, kind) {\n  const s = portSeries(rows, fx, target); if (!s || s.values.length < 3) return null;\n  const v = kind === 'stock' ? s.values.slice(-6) : s.values;\n  if (v.length < 3 || !(v[0] > 0)) return null;\n  const mv = rows.filter((r) => r.it && num(r.it.c7) !== null && r.c.value !== null).sort((a, b) => b.it.c7 - a.it.c7);\n  return { from: v[0], to: v[v.length - 1], abs: v[v.length - 1] - v[0], pct: (v[v.length - 1] / v[0] - 1) * 100, best: mv[0] || null, worst: mv.length > 1 ? mv[mv.length - 1] : null, used: s.used, total: s.total };\n}\n/* ---- Bildirim kuralları (tarayıcıda ve sunucuda aynı kod) ---- */\nconst fmtMoney = (v, cur) => new Intl.NumberFormat('tr-TR', { style: 'currency', currency: cur || 'TRY', minimumFractionDigits: Math.abs(v) >= 1 ? 2 : 0, maximumFractionDigits: Math.abs(v) >= 1 ? 2 : 6 }).format(v);\nconst alertDir = (target, price) => (target >= price ? 'up' : 'dn');\nconst alertHit = (a, price) => !a.done && num(price) !== null && num(a.price) !== null && (a.dir === 'up' ? price >= a.price : price <= a.price);\n// Fiyat alarmları: priceOf(a) güncel fiyatı verir (yoksa null). Tetiklenenler done=now olur (bir kez çalar).\nfunction alertsRun(alerts, priceOf, now) {\n  const msgs = [];\n  for (const a of alerts) {\n    const p = priceOf(a);\n    if (!alertHit(a, p)) continue;\n    a.done = now;\n    const sym = String(a.sym).toUpperCase();\n    if (a.n) msgs.push({ k: a.k, id: a.id, tag: 'al-' + a.u, title: `${a.name}: ${a.n}`, body: `${sym} şu an ${fmtMoney(p, a.ccy)}; eşik ${fmtMoney(a.price, a.ccy)} idi.` });\n    else msgs.push({ k: a.k, id: a.id, tag: 'al-' + a.u, title: `${a.name}: hedef fiyata ulaştı`, body: `${sym} şu an ${fmtMoney(p, a.ccy)}; ${a.dir === 'up' ? 'yukarı' : 'aşağı'} hedefin ${fmtMoney(a.price, a.ccy)} idi.` });\n  }\n  return msgs;\n}\n// Sinyali Azalt/Sat'a dönenler ve bir günde %8'den fazla oynayanlar (her biri günde bir kez). done: { anahtar: gün }.\nfunction watchMessages(watch, itemOf, prevSigs, done, day) {\n  const msgs = [], sigs = {}, nd = {};\n  for (const [k, d] of Object.entries(done || {})) if (d === day) nd[k] = d;\n  for (const w of watch) {\n    const it = itemOf(w); if (!it || !it.a || SIG_RANK[it.a.signal] === undefined) continue;\n    const s = it.a.signal, p = prevSigs && prevSigs[w.id];\n    sigs[w.id] = s;\n    if (p && p !== s && SIG_RANK[p] !== undefined && SIG_RANK[s] < SIG_RANK[p] && SIG_RANK[s] <= -1 && nd['s:' + w.id + s] !== day) {\n      nd['s:' + w.id + s] = day;\n      const why = (it.a.reasons || []).find((x) => x.pos === false);\n      msgs.push({ k: w.k, id: w.id, tag: 'sig-' + w.id, title: `${w.name}: sinyal ${s}`, body: `${p} → ${s}. ${(why && why.t) || 'Trend zayıfladı.'}` });\n    }\n    if (num(it.c24) !== null && Math.abs(it.c24) >= 8 && nd['m:' + w.id] !== day) {\n      nd['m:' + w.id] = day;\n      msgs.push({ k: w.k, id: w.id, tag: 'mv-' + w.id, title: `${w.name} bugün ${fmtP(it.c24)}`, body: 'Bir günde sert hareket etti. Detay için uygulamayı aç.' });\n    }\n  }\n  return { msgs, sigs, done: nd };\n}\n// Portföy risk puanı (0-100): tek varlığa yığılma, varlıkların kendi risk seviyesi, zayıf sinyaller, çeşitlilik ve stabil payı.\nfunction portRisk(rows, fx, target) {\n  const list = [];\n  for (const r of rows) {\n    if (r.c.value === null || !r.it || !r.it.a) continue;\n    const v = fxConv(r.c.value, r.c.cur, target, fx); if (v === null) return null;\n    if (v > 0) list.push({ sym: r.h.sym, v, a: r.it.a });\n  }\n  if (!list.length) return null;\n  list.sort((x, y) => y.v - x.v);\n  const tot = list.reduce((s, x) => s + x.v, 0), n = list.length;\n  const share = (list[0].v / tot) * 100;\n  const rank = (a) => (a.risk === 'Yüksek' ? 3 : a.risk === 'Orta' ? 2 : a.risk === 'Düşük' ? 1 : 2);\n  const avg = list.reduce((s, x) => s + x.v * rank(x.a), 0) / tot;\n  const weak = (list.filter((x) => x.a.signal === 'SAT' || x.a.signal === 'AZALT' || x.a.hot).reduce((s, x) => s + x.v, 0) / tot) * 100;\n  const stable = (list.filter((x) => x.a.signal === 'STABİL').reduce((s, x) => s + x.v, 0) / tot) * 100;\n  const pc = share >= 70 ? 35 : share >= 50 ? 28 : share >= 35 ? 18 : share >= 25 ? 10 : 4;\n  const pv = ((avg - 1) / 2) * 35;\n  const pw = Math.min(20, weak * 0.25);\n  const pn = n === 1 ? 10 : n === 2 ? 7 : n === 3 ? 4 : n <= 5 ? 2 : 0;\n  const ps = Math.min(25, stable * 0.3);\n  const score = Math.max(0, Math.min(100, Math.round(pc + pv + pw + pn - ps)));\n  const level = score < 25 ? 'Düşük' : score < 50 ? 'Orta' : score < 70 ? 'Yüksek' : 'Çok yüksek';\n  const why = [];\n  if (n === 1) why.push({ pos: false, t: 'Tek varlığın var: hepsi aynı anda düşebilir.' });\n  else if (share >= 35) why.push({ pos: false, t: `Portföyün %${Math.round(share)}'i tek varlıkta (${String(list[0].sym).toUpperCase()}).` });\n  else why.push({ pos: true, t: `En büyük varlık portföyün %${Math.round(share)}'i: dağılım dengeli.` });\n  if (avg >= 2.4) why.push({ pos: false, t: 'Varlıkların çoğu yüksek riskli (oynaklığı yüksek ya da küçük piyasa değerli).' });\n  else if (avg <= 1.5) why.push({ pos: true, t: 'Varlıkların çoğu düşük riskli.' });\n  else why.push({ pos: null, t: 'Varlıkların risk seviyesi orta.' });\n  if (weak >= 30) why.push({ pos: false, t: `Portföyün %${Math.round(weak)}'i zayıf sinyalli (Azalt/Sat) ya da aşırı ısınmış varlıklarda.` });\n  if (stable >= 20) why.push({ pos: true, t: `Portföyün %${Math.round(stable)}'i stabil varlıklarda; bu riski azaltır.` });\n  if (n >= 2 && n <= 3) why.push({ pos: null, t: 'Az sayıda varlık var; çeşitlendirmek riski azaltır.' });\n  return { score, level, share, n, why };\n}\n// Altın ve döviz tablosu (hep TL). Gram altın = ons fiyatı ÷ 31,1035 × dolar kuru. Altın kalemleri saf altın değerinden hesaplanır.\nconst FX_GOLD = [\n  ['fx:gold', 'Gram altın', 'gram', 1, 'Au', 'gram altın', '1 gram · 24 ayar'],\n  ['fx:ceyrek', 'Çeyrek altın', 'çeyrek', (1.75 * 0.916), '¼', 'çeyrek altın', '1,75 g · 22 ayar'],\n  ['fx:yarim', 'Yarım altın', 'yarım', (3.5 * 0.916), '½', 'yarım altın', '3,5 g · 22 ayar'],\n  ['fx:tam', 'Tam altın', 'tam', (7 * 0.916), '1', 'tam altın', '7 g · 22 ayar'],\n  ['fx:ata', 'Cumhuriyet (Ata) altını', 'ata', (7.216 * 0.916), 'At', 'Cumhuriyet altını', '7,216 g · 22 ayar'],\n  ['fx:22', '22 ayar altın (bilezik)', '22 ayar', 0.916, '22', 'gram 22 ayar altın', '1 gram · 22 ayar'],\n  ['fx:18', '18 ayar altın', '18 ayar', 0.75, '18', 'gram 18 ayar altın', '1 gram · 18 ayar'],\n  ['fx:14', '14 ayar altın', '14 ayar', 0.585, '14', 'gram 14 ayar altın', '1 gram · 14 ayar'],\n];\n// hr: dış kaynaktan (Trunçgil Finans) altın satış/alış fiyatları { 'fx:gold': { alis, satis } } (ons dolar cinsinden). Hesaplanan değerden %10'dan fazla ayrışanlar (hatalı ayrıştırma) kullanılmaz.\nfunction fxTable(usd, eur, ozUsd, chg, hr) {\n  const out = [], mk = (id, name, symbol, price, c24, x) => {\n    const h = hr && hr[id], k = id === 'fx:ons' ? usd : 1;\n    if (x && x.g && h && num(h.satis) !== null && Math.abs((h.satis * k) / price - 1) <= 0.1) out.push({ id, name, symbol, price: h.satis * k, c24, ...x, src: 'harem', alis: num(h.alis) !== null ? h.alis * k : null });\n    else out.push({ id, name, symbol, price, c24, ...x });\n  };\n  if (num(ozUsd) !== null && ozUsd > 0 && usd > 0) {\n    const gram = (ozUsd / 31.1035) * usd, ch = num(chg);\n    for (const [id, nm, sy, f, av, ul, sub] of FX_GOLD) mk(id, nm, sy, gram * f, ch, { g: true, av, ul, sub });\n    mk('fx:ons', 'Ons altın', 'ons', ozUsd * usd, ch, { g: true, av: 'oz', ul: 'ons altın', sub: '1 ons · ' + fmtMoney(ozUsd, 'USD') });\n  }\n  if (usd > 0) mk('fx:usd', 'Amerikan doları', 'USD', usd, null, { av: '$', ul: 'dolar', sub: '1 USD · TL' });\n  if (eur > 0) mk('fx:eur', 'Euro', 'EUR', eur, null, { av: '€', ul: 'euro', sub: '1 EUR · TL' });\n  return out;\n}\n// Sabah özeti: izlenen varlıkların dünkü en iyi/en kötüsü, zayıf sinyaller, dolar-euro-altın. Miktar/maliyet kullanılmaz.\nfunction morningMessage(watch, itemOf, fxt) {\n  const its = watch.map((w) => ({ w, it: itemOf(w) })).filter((x) => x.it && x.it.a && num(x.it.c24) !== null);\n  const parts = [];\n  if (its.length) {\n    its.sort((p, q) => q.it.c24 - p.it.c24);\n    const best = its[0], worst = its[its.length - 1];\n    if (its.length === 1) parts.push(`${best.w.name} son 24 saatte ${fmtP(best.it.c24)}.`);\n    else parts.push(`En çok yükselen ${best.w.name} ${fmtP(best.it.c24)}, en çok düşen ${worst.w.name} ${fmtP(worst.it.c24)}.`);\n    const weak = its.filter((x) => x.it.a.signal === 'SAT' || x.it.a.signal === 'AZALT').map((x) => x.w.name);\n    if (weak.length) parts.push(`Azalt/Sat sinyali: ${weak.slice(0, 3).join(', ')}${weak.length > 3 ? ' ve ' + (weak.length - 3) + ' varlık daha' : ''}.`);\n  }\n  const g = (id) => (fxt || []).find((x) => x.id === id);\n  const fx = [['fx:usd', 'Dolar'], ['fx:eur', 'Euro'], ['fx:gold', 'Gram altın']].map(([id, n]) => (g(id) ? `${n} ${fmtMoney(g(id).price, 'TRY')}` : '')).filter(Boolean);\n  if (fx.length) parts.push(fx.join(' · ') + '.');\n  if (!parts.length) return null;\n  return { tag: 'morning', title: 'Günaydın, piyasa özeti', body: parts.join(' ') };\n}\n// Yatırım planı: eldeki tutarı (TL) puanı yüksek, aşırı ısınmamış adaylara riske göre böler. Yatırım tavsiyesi değildir.\n// cands: [{ id, name, symbol, kind, a: { signal, score, risk, hot, reasons }, ptry }]; ptry: 1 birimin TL fiyatı (yoksa null). risk: 'dusuk' | 'orta' | 'yuksek'.\nfunction planInvest(cands, amount, risk) {\n  const rk = (x) => (x.a.risk === 'Yüksek' ? 3 : x.a.risk === 'Orta' ? 2 : 1);\n  const maxRisk = { dusuk: 1, orta: 2, yuksek: 3 }[risk] || 2, cashPct = { dusuk: 20, orta: 10, yuksek: 0 }[risk] ?? 10;\n  if (!(amount > 0)) return null;\n  const pool = cands.filter((x) => x.a && (x.a.signal === 'AL' || x.a.signal === 'GÜÇLÜ AL') && x.a.score >= 20 && !x.a.hot && rk(x) <= maxRisk).sort((p, q) => q.a.score - p.a.score);\n  const n = Math.min(pool.length, amount >= 100000 ? 5 : amount >= 20000 ? 4 : 3);\n  if (!n) return { wait: true, picks: [], cash: amount, amount, pool: 0 };\n  const top = pool.slice(0, n);\n  let w = top.map((x) => x.a.score / rk(x));\n  const sum0 = w.reduce((s, v) => s + v, 0); w = w.map((v) => v / sum0);\n  const cap = n >= 3 ? 0.4 : n === 2 ? 0.6 : 1;\n  for (let k = 0; k < 4; k++) {\n    const over = w.reduce((s, v) => s + Math.max(0, v - cap), 0); if (over < 1e-9) break;\n    const free = w.filter((v) => v < cap).reduce((s, v) => s + v, 0);\n    w = w.map((v) => (v >= cap ? cap : free > 0 ? v + (over * v) / free : v));\n  }\n  const invFrac = (1 - cashPct / 100) * (n >= 3 ? 1 : n === 2 ? 0.8 : 0.5), invested = amount * invFrac;\n  let spent = 0;\n  const picks = top.map((x, i) => {\n    const share = w[i] * invFrac, tl = invested * w[i];\n    let qty = null, used = tl;\n    if (num(x.ptry) !== null && x.ptry > 0) {\n      // BIST hissesi tam adet alınır; ABD hissesi (Midas'ta kesirli alınabilir) ve coin kesirli.\n      qty = x.kind === 'stock' && (x.cur || 'TRY') === 'TRY' ? Math.floor(tl / x.ptry) : x.kind === 'stock' ? Math.floor((tl / x.ptry) * 1e4) / 1e4 : Number((tl / x.ptry).toPrecision(6));\n      used = qty * x.ptry;\n    }\n    spent += used;\n    const why = (x.a.reasons || []).filter((r) => r.pos === true).slice(0, 2).map((r) => r.t);\n    return { id: x.id, name: x.name, symbol: x.symbol, kind: x.kind, cur: x.cur || 'TRY', signal: x.a.signal, score: x.a.score, risk: x.a.risk, share, tl, qty, used, why };\n  });\n  return { wait: false, picks, cash: amount - spent, amount, pool: pool.length, cashPct, n };\n}\n// ---- Araçlar: geçmiş fiyat serileri (zaman sıralı t[], v[]) üzerinde hesaplar ----\n// En yakın noktanın değeri (iki yönde). maxGap ms'den uzaksa null.\nfunction valNear(t, v, ts, maxGap) {\n  if (!t || !t.length) return null;\n  let lo = 0, hi = t.length - 1;\n  while (lo < hi) { const m = (lo + hi) >> 1; if (t[m] < ts) lo = m + 1; else hi = m; }\n  let best = lo; if (lo > 0 && Math.abs(t[lo - 1] - ts) <= Math.abs(t[lo] - ts)) best = lo - 1;\n  return maxGap && Math.abs(t[best] - ts) > maxGap ? null : v[best];\n}\n// İki seriyi zaman üzerinden çarpar (ör. coinin dolar fiyatı × dolar kuru = TL fiyatı). Eşi bulunamayan nokta atlanır.\nfunction mulSeries(a, b, k, maxGap) {\n  const t = [], v = [];\n  for (let i = 0; i < a.t.length; i++) { const f = valNear(b.t, b.v, a.t[i], maxGap || 10 * 86400e3); if (f !== null && f > 0) { t.push(a.t[i]); v.push(a.v[i] * f * (k || 1)); } }\n  return { t, v };\n}\n// \"Keşke alsaydım\": fromTs tarihinde amount kadar alınsaydı bugün ne olurdu.\nfunction whatIf(t, v, fromTs, amount) {\n  if (!t || t.length < 2 || !(amount > 0)) return null;\n  let i = t.findIndex((x) => x >= fromTs); if (i < 0) return null;\n  const short = t[0] > fromTs + 5 * 86400e3;\n  if (i >= t.length - 1) i = t.length - 2;\n  const buy = v[i], now = v[v.length - 1]; if (!(buy > 0) || !(now > 0)) return null;\n  const units = amount / buy, value = units * now;\n  let mi = i, ma = i; for (let j = i; j < v.length; j++) { if (v[j] < v[mi]) mi = j; if (v[j] > v[ma]) ma = j; }\n  return { date: t[i], buy, now, units, value, gain: value - amount, pct: (value / amount - 1) * 100, short, first: t[0], low: units * v[mi], lowDate: t[mi], high: units * v[ma], highDate: t[ma] };\n}\n// Düzenli alım: her ay \"day\" gününde (o gün veri yoksa sonraki ilk veri) monthly kadar alınır.\nfunction dcaSim(t, v, monthly, months, day, nowTs) {\n  if (!t || t.length < 2 || !(monthly > 0) || !(months > 0)) return null;\n  const end = new Date(nowTs || t[t.length - 1]), buys = [];\n  for (let m = months; m >= 0; m--) { // bu ayın alım günü henüz gelmediyse bir önceki aydan başlanır\n    const y = end.getUTCFullYear(), mo = end.getUTCMonth() - m, last = new Date(Date.UTC(y, mo + 1, 0)).getUTCDate();\n    const ts = Date.UTC(y, mo, Math.min(day || 1, last), 12);\n    if (ts > t[t.length - 1]) continue;\n    const i = t.findIndex((x) => x >= ts - 12 * 3600e3); if (i < 0 || t[i] - ts > 20 * 86400e3) continue;\n    if (buys.length && buys[buys.length - 1].i === i) continue;\n    buys.push({ i, t: t[i], p: v[i], q: monthly / v[i] });\n  }\n  if (buys.length > months) buys.splice(0, buys.length - months);\n  if (!buys.length) return null;\n  const units = buys.reduce((s, b) => s + b.q, 0), invested = monthly * buys.length, now = v[v.length - 1], value = units * now;\n  const lump = (invested / buys[0].p) * now;\n  const path = []; let k = 0, q = 0;\n  for (let j = buys[0].i; j < t.length; j++) { while (k < buys.length && buys[k].i <= j) { q += buys[k].q; k++; } path.push([t[j], monthly * k, q * v[j]]); }\n  return { n: buys.length, invested, units, value, gain: value - invested, pct: (value / invested - 1) * 100, avg: invested / units, now, lump, lumpPct: (lump / invested - 1) * 100, first: buys[0].t, short: buys.length < months, path };\n}\n// Karşılaştırma için özet: dönem getirileri, oynaklık (yıllık), en büyük düşüş.\nfunction seriesStats(t, v) {\n  if (!t || t.length < 3) return null;\n  const last = v[v.length - 1], end = t[t.length - 1];\n  const back = (d) => { const ts = end - d * 86400e3; if (t[0] > ts + 4 * 86400e3) return null; const p = valNear(t, v, ts); return p > 0 ? (last / p - 1) * 100 : null; };\n  const r = []; for (let i = 1; i < v.length; i++) if (v[i - 1] > 0 && v[i] > 0) r.push(Math.log(v[i] / v[i - 1]));\n  const mean = r.reduce((s, x) => s + x, 0) / (r.length || 1), sd = Math.sqrt(r.reduce((s, x) => s + (x - mean) ** 2, 0) / Math.max(1, r.length - 1));\n  const gaps = []; for (let i = 1; i < t.length; i++) gaps.push(t[i] - t[i - 1]); gaps.sort((a, b) => a - b);\n  const step = gaps[gaps.length >> 1] || 86400e3, ppy = (365 * 86400e3) / step;\n  let peak = v[0], dd = 0; for (const x of v) { if (x > peak) peak = x; if (peak > 0) dd = Math.min(dd, (x / peak - 1) * 100); }\n  return { c30: back(30), c90: back(90), c365: back(365), all: v[0] > 0 ? (last / v[0] - 1) * 100 : null, vol: sd * Math.sqrt(ppy) * 100, dd, from: t[0] };\n}\n\n// ---- Ekonomi takvimi (Türkiye saati). Kaynak: TCMB, Fed, ECB ve ABD Çalışma Bakanlığı (BLS) takvimleri. TÜİK: ayın 3'ü, hafta sonuna denk gelirse pazartesi. ----\nconst ECO_INFO = {\n  tcmb: ['TCMB faiz kararı', 'Türkiye\\'nin politika faizi açıklanır. TL, Borsa İstanbul ve altın doğrudan etkilenir.', 3],\n  tuik: ['Türkiye enflasyonu (TÜİK)', 'Geçen ayın enflasyonu açıklanır. Beklentiden yüksek gelirse faiz ve TL üzerinde baskı oluşur.', 3],\n  fed: ['ABD Fed faiz kararı', 'ABD\\'nin faiz kararı. Doların, ABD hisselerinin ve kriptonun yönünü en çok etkileyen gün.', 3],\n  cpi: ['ABD enflasyonu', 'ABD\\'nin aylık enflasyon verisi. Fed\\'in sonraki adımına dair beklentiyi değiştirir; kripto sert oynayabilir.', 3],\n  nfp: ['ABD istihdam verisi', 'ABD\\'de tarım dışı istihdam. Ekonominin gücünü gösterir; dolar ve hisseler oynayabilir.', 2],\n  ecb: ['Avrupa Merkez Bankası faiz kararı', 'Euro bölgesinin faiz kararı. Euro kurunu ve Avrupa hisselerini etkiler.', 2],\n  tcmbr: ['TCMB Enflasyon Raporu', 'Merkez Bankası enflasyon tahminlerini günceller. TL ve faiz beklentileri değişebilir.', 2],\n};\nconst ECO_RAW = 'tcmb 2026-10-22 14:00,fed 2026-10-28 21:00,ecb 2026-10-29 16:15,nfp 2026-11-06 16:30,cpi 2026-11-10 16:30,tcmbr 2026-11-12 10:30,nfp 2026-12-04 16:30,fed 2026-12-09 22:00,cpi 2026-12-10 16:30,tcmb 2026-12-10 14:00,ecb 2026-12-17 16:15,'\n  + 'nfp 2027-01-08 16:30,cpi 2027-01-13 16:30,tcmb 2027-01-21 14:00,fed 2027-01-27 22:00,ecb 2027-02-04 16:15,nfp 2027-02-05 16:30,cpi 2027-02-11 16:30,tcmbr 2027-02-11 10:30,nfp 2027-03-05 16:30,cpi 2027-03-10 16:30,fed 2027-03-17 21:00,tcmb 2027-03-18 14:00,ecb 2027-03-18 16:15,'\n  + 'nfp 2027-04-02 15:30,cpi 2027-04-13 15:30,tcmb 2027-04-22 14:00,fed 2027-04-28 21:00,ecb 2027-04-29 15:15,nfp 2027-05-07 15:30,cpi 2027-05-12 15:30,tcmbr 2027-05-13 10:30,nfp 2027-06-04 15:30,fed 2027-06-09 21:00,cpi 2027-06-10 15:30,tcmb 2027-06-10 14:00,ecb 2027-06-10 15:15,'\n  + 'nfp 2027-07-02 15:30,cpi 2027-07-14 15:30,ecb 2027-07-22 15:15,fed 2027-07-28 21:00,nfp 2027-08-06 15:30,cpi 2027-08-11 15:30,nfp 2027-09-03 15:30,ecb 2027-09-09 15:15,cpi 2027-09-14 15:30,fed 2027-09-15 21:00,nfp 2027-10-08 15:30,cpi 2027-10-14 15:30,fed 2027-10-27 21:00,ecb 2027-10-28 15:15,'\n  + 'nfp 2027-11-05 15:30,cpi 2027-11-10 16:30,nfp 2027-12-03 16:30,fed 2027-12-08 22:00,cpi 2027-12-10 16:30,ecb 2027-12-16 16:15';\nconst ECO_END = '2027-12-31';\nfunction ecoList() {\n  const l = ECO_RAW.split(',').map((s) => { const [c, d, h] = s.trim().split(' '); return { c, d, h }; });\n  for (let y = 2026, m = 11; y < 2028; m === 12 ? (y++, m = 1) : m++) {\n    const dt = new Date(Date.UTC(y, m - 1, 3)), wd = dt.getUTCDay(); if (wd === 6) dt.setUTCDate(5); else if (wd === 0) dt.setUTCDate(4);\n    l.push({ c: 'tuik', d: dt.toISOString().slice(0, 10), h: '10:00', approx: true });\n  }\n  return l.map((e) => { const [y, mo, d] = e.d.split('-').map(Number), [hh, mm] = e.h.split(':').map(Number), inf = ECO_INFO[e.c];\n    return { ...e, name: inf[0], desc: inf[1], imp: inf[2], ts: Date.UTC(y, mo - 1, d, hh - 3, mm) }; }).sort((a, b) => a.ts - b.ts);\n}\n// fromDay (YYYY-MM-DD, Türkiye) dahil, days gün içindeki olaylar.\nfunction ecoBetween(fromDay, days) { const s = Date.parse(fromDay + 'T00:00:00+03:00'), e = s + days * 86400e3; return ecoList().filter((x) => x.ts >= s && x.ts < e); }\nconst ECO_GUN = ['Pazar', 'Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi'];\nfunction ecoTomorrowMessage(day) {\n  const next = new Date(Date.parse(day + 'T12:00:00+03:00') + 86400e3).toISOString().slice(0, 10), l = ecoBetween(next, 1);\n  if (!l.length) return null;\n  return { k: 'r', id: 'cal', tag: 'cal-' + next, title: 'Yarın: ' + l.map((x) => x.name).join(', '), body: l.map((x) => `${x.h} ${x.name}`).join(' · ') + '. Fiyatlar bu saatlerde sert oynayabilir.' };\n}\n// Pazar akşamı haftalık rapor: izlenen varlıkların 7 günlük değişimi (miktar ve maliyet kullanılmaz) ve gelecek haftanın takvimi.\nfunction weeklyMessage(watch, itemOf, day) {\n  const its = watch.map((w) => ({ w, it: itemOf(w) })).filter((x) => x.it && num(x.it.c7) !== null);\n  const parts = [];\n  if (its.length) {\n    its.sort((p, q) => q.it.c7 - p.it.c7);\n    const avg = its.reduce((s, x) => s + x.it.c7, 0) / its.length;\n    parts.push(its.length === 1 ? `${its[0].w.name} bu hafta ${fmtP(its[0].it.c7)}.` : `İzlediğin ${its.length} varlık bu hafta ortalama ${fmtP(avg)}. En iyi ${its[0].w.name} ${fmtP(its[0].it.c7)}, en kötü ${its[its.length - 1].w.name} ${fmtP(its[its.length - 1].it.c7)}.`);\n    const weak = its.filter((x) => x.it.a && (x.it.a.signal === 'SAT' || x.it.a.signal === 'AZALT')).map((x) => x.w.name);\n    if (weak.length) parts.push(`Azalt/Sat sinyali: ${weak.slice(0, 3).join(', ')}.`);\n  }\n  const nx = ecoBetween(new Date(Date.parse(day + 'T12:00:00+03:00') + 86400e3).toISOString().slice(0, 10), 7).filter((x) => x.imp >= 3);\n  if (nx.length) parts.push('Gelecek hafta: ' + nx.slice(0, 3).map((x) => `${x.name} (${ECO_GUN[new Date(x.ts + 3 * 3600e3).getUTCDay()]})`).join(', ') + '.');\n  if (!parts.length) return null;\n  return { k: 'r', id: 'week', tag: 'weekly-' + day, title: 'Haftalık rapor', body: parts.join(' ') + ' Ayrıntı için dokun.' };\n}\n\n;return { analyze, newsContext, buildStockWorld, watchMessages, alertsRun, alertHit, fmtMoney, fxTable, morningMessage, weeklyMessage, ecoTomorrowMessage, ecoBetween, SIG_RANK, num };")();
